def length_of_longest_substring(s: str) -> int:
    seen = set()
    l, max_len = 0, 0
    for r in range(len(s)):
        while s[r] in seen:
            seen.remove(s[l])   # Evict left until window character is unique
            l += 1
        seen.add(s[r])
        max_len = max(max_len, r - l + 1)  # Track global maximum distance
    return max_len

def two_sum_sorted(numbers: list[int], target: int) -> list[int]:
    l, r = 0, len(numbers) - 1
    while l < r:
        cur = numbers[l] + numbers[r]
        if cur == target:
            return [l + 1, r + 1]  # Return 1-indexed positions
        elif cur < target:
            l += 1  # Sum too small, move left pointer rightward
        else:
            r -= 1  # Sum too large, move right pointer leftward
    return []

def has_cycle(head: Optional[ListNode]) -> bool:
    slow, fast = head, head
    while fast and fast.next:
        slow = slow.next        # Moves 1 node at a time
        fast = fast.next.next   # Moves 2 nodes at a time
        if slow == fast:
            return True         # Fast caught up to slow (cycle detected)
    return False

def remove_duplicates(nums: list[int]) -> int:
    if not nums: return 0
    slow = 0  # Points to the last unique element found
    for fast in range(1, len(nums)):
        if nums[fast] != nums[slow]:
            slow += 1  # Move unique zone boundary
            nums[slow] = nums[fast]  # Overwrite with new item
    return slow + 1

parent = list(range(n))
rank = [0] * n

def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]   # path compression (halving)
        x = parent[x]
    return x

def union(a, b):
    ra, rb = find(a), find(b)
    if ra == rb:
        return False            # already connected → (for cycle detection) this edge is redundant
    if rank[ra] < rank[rb]:
        ra, rb = rb, ra
    parent[rb] = ra
    if rank[ra] == rank[rb]:
        rank[ra] += 1
    return True
